STOCK_BYTES=118525
STOCK_SHA256='e3895fc9d0d20943f05f4d6e648eb5fd54808bba763be597e2105008b997a889'
HEADER_PATH='drivers/optics/tcs3407.h'
HEADER_SHA256='c154b4eca1566971983b2a50e94b9d991659e8a843c24f341fdde59a6fbe3825'
REQUIRED_CONFIG={'SENSORS_TCS3407':'y','PWM':'y','PWM_SYSFS':'y','PWM_SAMSUNG':'y','PINCTRL':'y','PINCTRL_SAMSUNG':'y','I2C':'y','SYSFS':'y','LEDS_S2MPB02':'n'}
BEFORE=b'static ssize_t tcs3407_debug_store(struct device *dev,\n\tstruct device_attribute *attr, const char *buf, size_t size)\n{\n\tstruct tcs3407_device_data *data = dev_get_drvdata(dev);\n\tint err;\n\ts32 mode;\n\tstruct pwm_state state;\n\tint period = 10000000; /* nano secs */\n\tint period2 = 8333333; /* nano secs */\n\tint duty_cycle = 5000000;\n\n\tif(data->pwm)\n\t\tpwm_get_state(data->pwm, &state);\n\n\tstate.enabled = 1;\n\tstate.period = period; /* nano secs */\n\tif (debug_pwm_duty)\n\t\tduty_cycle = debug_pwm_duty;\n\n\tstate.duty_cycle = duty_cycle;\n\tstate.polarity = PWM_POLARITY_NORMAL; // should be default low\n\n\tmutex_lock(&data->activelock);\n\terr = kstrtoint(buf, 10, &mode);\n\tif (err < 0) {\n\t\tALS_err("%s - kstrtoint failed.(%d)\\n", __func__, err);\n\t\tmutex_unlock(&data->activelock);\n\t\treturn err;\n\t}\n\tdata->debug_mode = mode;\n\tALS_info("%s - mode = %d\\n", __func__, mode);\n\n\tswitch (data->debug_mode) {\n\tcase DEBUG_REG_STATUS:\n\t\ttcs3407_print_reg_status();\n\t\tbreak;\n\tcase DEBUG_VAR:\n\t\ttcs3407_debug_var(data);\n\t\tbreak;\n\tcase 3:\n\t\tpinctrl_select_state(data->als_pinctrl,\tdata->pinctrl_pwm);\n\t\tpwm_apply_state(data->pwm, &state);\n\t\tbreak;\n\tcase 4:\n\t\tstate.period = period2;\n\t\tpwm_apply_state(data->pwm, &state);\n\t\tbreak;\n\tdefault:\n\t\tdebug_pwm_duty = data->debug_mode;\n\t\tbreak;\n\t}\n\tmutex_unlock(&data->activelock);\n\n\treturn size;\n}\n'
AFTER=b'static ssize_t tcs3407_debug_store(struct device *dev,\n\tstruct device_attribute *attr, const char *buf, size_t size)\n{\n\tstruct tcs3407_device_data *data = dev_get_drvdata(dev);\n\tint err;\n\ts32 mode;\n#ifdef CONFIG_AMS_OPTICAL_SENSOR_EOL_MODE\n\tstruct pwm_state state;\n\tint period = 10000000; /* nano secs */\n\tint period2 = 8333333; /* nano secs */\n\tint duty_cycle = 5000000;\n\n\tif(data->pwm)\n\t\tpwm_get_state(data->pwm, &state);\n\n\tstate.enabled = 1;\n\tstate.period = period; /* nano secs */\n\tif (debug_pwm_duty)\n\t\tduty_cycle = debug_pwm_duty;\n\n\tstate.duty_cycle = duty_cycle;\n\tstate.polarity = PWM_POLARITY_NORMAL; // should be default low\n\n#endif\n\tmutex_lock(&data->activelock);\n\terr = kstrtoint(buf, 10, &mode);\n\tif (err < 0) {\n\t\tALS_err("%s - kstrtoint failed.(%d)\\n", __func__, err);\n\t\tmutex_unlock(&data->activelock);\n\t\treturn err;\n\t}\n#ifndef CONFIG_AMS_OPTICAL_SENSOR_EOL_MODE\n\tif (mode != DEBUG_REG_STATUS && mode != DEBUG_VAR) {\n\t\tmutex_unlock(&data->activelock);\n\t\treturn -EOPNOTSUPP;\n\t}\n#endif\n\tdata->debug_mode = mode;\n\tALS_info("%s - mode = %d\\n", __func__, mode);\n\n\tswitch (data->debug_mode) {\n\tcase DEBUG_REG_STATUS:\n\t\ttcs3407_print_reg_status();\n\t\tbreak;\n\tcase DEBUG_VAR:\n\t\ttcs3407_debug_var(data);\n\t\tbreak;\n#ifdef CONFIG_AMS_OPTICAL_SENSOR_EOL_MODE\n\tcase 3:\n\t\tpinctrl_select_state(data->als_pinctrl,\tdata->pinctrl_pwm);\n\t\tpwm_apply_state(data->pwm, &state);\n\t\tbreak;\n\tcase 4:\n\t\tstate.period = period2;\n\t\tpwm_apply_state(data->pwm, &state);\n\t\tbreak;\n#endif\n\tdefault:\n#ifdef CONFIG_AMS_OPTICAL_SENSOR_EOL_MODE\n\t\tdebug_pwm_duty = data->debug_mode;\n#endif\n\t\tbreak;\n\t}\n\tmutex_unlock(&data->activelock);\n\n\treturn size;\n}\n'
UNSUPPORTED=b'#ifndef CONFIG_AMS_OPTICAL_SENSOR_EOL_MODE\n\tif (mode != DEBUG_REG_STATUS && mode != DEBUG_VAR) {\n\t\tmutex_unlock(&data->activelock);\n\t\treturn -EOPNOTSUPP;\n\t}\n#endif\n'


def prepare(raw):
    if type(raw)is not bytes or len(raw)!=STOCK_BYTES or hashlib.sha256(raw).hexdigest()!=STOCK_SHA256:
        raise ValueError('exact accepted stock TCS3407 source required')
    if raw.count(BEFORE)!=1 or AFTER in raw:
        raise ValueError('unique unmodified debug_store preimage required')
    return raw.replace(BEFORE,AFTER,1)
